    55→impl<ChainSpec, N> FullConsensus<N> for EthBeaconConsensus<ChainSpec>
    56→where
    57→    ChainSpec: Send + Sync + EthChainSpec<Header = N::BlockHeader> + EthereumHardforks + Debug,
