    69→impl<B, ChainSpec> Consensus<B> for EthBeaconConsensus<ChainSpec>
    70→where
    71→    B: Block,
    72→    ChainSpec: EthChainSpec<Header = B::Header> + EthereumHardforks + Debug + Send + Sync,
    73→{
