    27→macro_rules! delegate {
    28→    ($self:expr => $tx:ident.$method:ident($($arg:expr),*)) => {
    29→        match $self {
    30→            Transaction::Legacy($tx) => $tx.$method($($arg),*),
    31→            Transaction::Eip2930($tx) => $tx.$method($($arg),*),
    32→            Transaction::Eip1559($tx) => $tx.$method($($arg),*),
    33→            Transaction::Eip4844($tx) => $tx.$method($($arg),*),
    34→            Transaction::Eip7702($tx) => $tx.$method($($arg),*),
    35→        }
