    39→/// A raw transaction.
    40→///
    41→/// Transaction types were introduced in [EIP-2718](https://eips.ethereum.org/EIPS/eip-2718).
    42→#[derive(Debug, Clone, PartialEq, Eq, Hash, derive_more::From)]
    43→#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
    44→#[cfg_attr(any(test, feature = "arbitrary"), derive(arbitrary::Arbitrary))]
    45→#[cfg_attr(any(test, feature = "reth-codec"), reth_codecs::add_arbitrary_tests(compact))]
    46→pub enum Transaction {
    47→    /// Legacy transaction (type `0x0`).
    48→    ///
    49→    /// Traditional Ethereum transactions, containing parameters `nonce`, `gasPrice`, `gasLimit`,
    50→    /// `to`, `value`, `data`, `v`, `r`, and `s`.
    51→    ///
    52→    /// These transactions do not utilize access lists nor do they incorporate EIP-1559 fee market
    53→    /// changes.
    54→    Legacy(TxLegacy),
    55→    /// Transaction with an [`AccessList`] ([EIP-2930](https://eips.ethereum.org/EIPS/eip-2930)), type `0x1`.
    56→    ///
    57→    /// The `accessList` specifies an array of addresses and storage keys that the transaction
    58→    /// plans to access, enabling gas savings on cross-contract calls by pre-declaring the accessed
    59→    /// contract and storage slots.
    60→    Eip2930(TxEip2930),
    61→    /// A transaction with a priority fee ([EIP-1559](https://eips.ethereum.org/EIPS/eip-1559)), type `0x2`.
    62→    ///
    63→    /// Unlike traditional transactions, EIP-1559 transactions use an in-protocol, dynamically
    64→    /// changing base fee per gas, adjusted at each block to manage network congestion.
    65→    ///
    66→    /// - `maxPriorityFeePerGas`, specifying the maximum fee above the base fee the sender is
    67→    ///   willing to pay
    68→    /// - `maxFeePerGas`, setting the maximum total fee the sender is willing to pay.
    69→    ///
    70→    /// The base fee is burned, while the priority fee is paid to the miner who includes the
    71→    /// transaction, incentivizing miners to include transactions with higher priority fees per
    72→    /// gas.
    73→    Eip1559(TxEip1559),
    74→    /// Shard Blob Transactions ([EIP-4844](https://eips.ethereum.org/EIPS/eip-4844)), type `0x3`.
    75→    ///
    76→    /// Shard Blob Transactions introduce a new transaction type called a blob-carrying transaction
    77→    /// to reduce gas costs. These transactions are similar to regular Ethereum transactions but
    78→    /// include additional data called a blob.
    79→    ///
    80→    /// Blobs are larger (~125 kB) and cheaper than the current calldata, providing an immutable
    81→    /// and read-only memory for storing transaction data.
    82→    ///
    83→    /// EIP-4844, also known as proto-danksharding, implements the framework and logic of
    84→    /// danksharding, introducing new transaction formats and verification rules.
    85→    Eip4844(TxEip4844),
    86→    /// EOA Set Code Transactions ([EIP-7702](https://eips.ethereum.org/EIPS/eip-7702)), type `0x4`.
    87→    ///
    88→    /// EOA Set Code Transactions give the ability to set contract code for an EOA in perpetuity
    89→    /// until re-assigned by the same EOA. This allows for adding smart contract functionality to
    90→    /// the EOA.
    91→    Eip7702(TxEip7702),
    92→}
