   562→impl reth_codecs::Compact for TransactionSigned {
   563→    fn to_compact<B>(&self, buf: &mut B) -> usize
   564→    where
   565→        B: alloy_rlp::bytes::BufMut + AsMut<[u8]>,
   566→    {
   567→        use alloy_consensus::Transaction;
   568→
   569→        let start = buf.as_mut().len();
   570→
   571→        // Placeholder for bitflags.
   572→        // The first byte uses 4 bits as flags: IsCompressed[1bit], TxType[2bits], Signature[1bit]
   573→        buf.put_u8(0);
   574→
   575→        let sig_bit = self.signature.to_compact(buf) as u8;
   576→        let zstd_bit = self.transaction.input().len() >= 32;
   577→
   578→        let tx_bits = if zstd_bit {
   579→            let mut tmp = Vec::with_capacity(256);
   580→            if cfg!(feature = "std") {
   581→                reth_zstd_compressors::TRANSACTION_COMPRESSOR.with(|compressor| {
   582→                    let mut compressor = compressor.borrow_mut();
   583→                    let tx_bits = self.transaction.to_compact(&mut tmp);
   584→                    buf.put_slice(&compressor.compress(&tmp).expect("Failed to compress"));
   585→                    tx_bits as u8
   586→                })
   587→            } else {
   588→                let mut compressor = reth_zstd_compressors::create_tx_compressor();
   589→                let tx_bits = self.transaction.to_compact(&mut tmp);
   590→                buf.put_slice(&compressor.compress(&tmp).expect("Failed to compress"));
   591→                tx_bits as u8
   592→            }
   593→        } else {
   594→            self.transaction.to_compact(buf) as u8
   595→        };
   596→
   597→        // Replace bitflags with the actual values
   598→        buf.as_mut()[start] = sig_bit | (tx_bits << 1) | ((zstd_bit as u8) << 3);
   599→
   600→        buf.as_mut().len() - start
   601→    }
   602→
   603→    fn from_compact(mut buf: &[u8], _len: usize) -> (Self, &[u8]) {
   604→        use alloy_rlp::bytes::Buf;
   605→
   606→        // The first byte uses 4 bits as flags: IsCompressed[1], TxType[2], Signature[1]
   607→        let bitflags = buf.get_u8() as usize;
   608→
   609→        let sig_bit = bitflags & 1;
   610→        let (signature, buf) = Signature::from_compact(buf, sig_bit);
   611→
   612→        let zstd_bit = bitflags >> 3;
   613→        let (transaction, buf) = if zstd_bit != 0 {
   614→            if cfg!(feature = "std") {
   615→                reth_zstd_compressors::TRANSACTION_DECOMPRESSOR.with(|decompressor| {
   616→                    let mut decompressor = decompressor.borrow_mut();
   617→
   618→                    // TODO: enforce that zstd is only present at a "top" level type
   619→
   620→                    let transaction_type = (bitflags & 0b110) >> 1;
   621→                    let (transaction, _) =
   622→                        Transaction::from_compact(decompressor.decompress(buf), transaction_type);
   623→
   624→                    (transaction, buf)
   625→                })
   626→            } else {
   627→                let mut decompressor = reth_zstd_compressors::create_tx_decompressor();
   628→                let transaction_type = (bitflags & 0b110) >> 1;
   629→                let (transaction, _) =
   630→                    Transaction::from_compact(decompressor.decompress(buf), transaction_type);
   631→
   632→                (transaction, buf)
   633→            }
   634→        } else {
   635→            let transaction_type = bitflags >> 1;
   636→            Transaction::from_compact(buf, transaction_type)
   637→        };
   638→
   639→        (Self { signature, transaction, hash: Default::default() }, buf)
   640→    }
   641→}
